const v = $input.first().json;
const m = v.messages?.[0];
if (!m) return [];                       // delivery/read receipts

const phone = String(m.from).replace(/\D/g, '');
let text = '';
if (m.type === 'text') text = m.text?.body ?? '';
else if (m.type === 'interactive') {
  const tap = m.interactive?.button_reply ?? m.interactive?.list_reply;
  const id = String(tap?.id ?? '');
  text = (id.startsWith('acc:') || id.startsWith('q:')) ? id : (tap?.title ?? '');
} else if (m.type === 'contacts') {
  // a shared contact card: the access menu uses it to add that person
  const c = m.contacts?.[0] ?? {};
  const p = (c.phones ?? []).find(x => x.wa_id) ?? (c.phones ?? [])[0] ?? {};
  const num = String(p.wa_id ?? p.phone ?? '').replace(/\D/g, '');
  const nm = String(c.name?.formatted_name ?? c.name?.first_name ?? '').replace(/[:\r\n]/g, ' ').trim().slice(0, 60);
  if (num) text = `acc:contact:${num}:${nm}`;
}

const ist = new Date(Date.now() + 5.5 * 3600 * 1000);
const y = ist.getUTCFullYear(), mo = ist.getUTCMonth();
const iso = (yy, mm, dd) => new Date(Date.UTC(yy, mm, dd)).toISOString().slice(0, 10);
const fy = mo >= 3 ? y : y - 1;
const qs = (3 + Math.floor(((mo + 9) % 12) / 3) * 3) % 12;
const qy = qs > mo ? y - 1 : y;
const anchors = {
  today: iso(y, mo, ist.getUTCDate()),
  this_month: [iso(y, mo, 1), iso(y, mo + 1, 0)],
  last_month: [iso(y, mo - 1, 1), iso(y, mo, 0)],
  this_quarter: [iso(qy, qs, 1), iso(qy, qs + 3, 0)],
  this_fy: [iso(fy, 3, 1), iso(fy + 1, 2, 31)],
  last_fy: [iso(fy - 1, 3, 1), iso(fy, 2, 31)]
};
return [{ json: { phone, wamid: m.id, type: m.type, text: text.trim().slice(0, 1000), anchors } }];

const n = $('Normalize').first().json;
const ctx = $input.first().json.ctx;
const role = $('Route access').first().json.r?.role || {};
const owns = role.owner_of || [];
const roleLine = role.is_admin
  ? 'admin (can manage people for every company)'
  : owns.length ? `owner of ${owns.join(', ')} (can add and remove viewers there)` : 'viewer (can ask questions only)';
const list = ctx.companies.map((c, i) => `${i + 1}. ${c.name}  [id: ${c.id}]`).join('\n');
const active = ctx.active_company_id
  ? `ACTIVE COMPANY: ${ctx.active_company_name}\nSYNC: ${JSON.stringify(ctx.sync)}`
  : 'ACTIVE COMPANY: none selected yet';
return [{ json: { ...n, context_block:
`USER: ${ctx.user_name ?? 'unknown'}
YOUR ROLE: ${roleLine}
TODAY (IST): ${n.anchors.today}
DATE ANCHORS: ${JSON.stringify(n.anchors)}
AUTHORIZED COMPANIES (${ctx.company_count}):
${list}
${active}` } }];

let t = String($input.first().json.output ?? '').trim();
t = t.replace(/\*\*(.+?)\*\*/g, '*$1*').replace(/^#{1,6}\s*/gm, '').replace(/\b[0-9a-f]{32}\b/g, '');
const parts = [];
while (t.length > 3800) {
  let cut = t.lastIndexOf('\n', 3800); if (cut < 1000) cut = 3800;
  parts.push(t.slice(0, cut)); t = t.slice(cut).trim();
}
parts.push(t);
return parts.filter(Boolean).map(p => ({ json: { to: $('Normalize').first().json.phone, text: p } }));

const r = $input.first().json.r;
const cut = (s, n) => String(s ?? '').slice(0, n);
return (r.replies || []).filter(x => x && x.to && x.text).map(x => {
  let payload = null;
  if (Array.isArray(x.buttons) && x.buttons.length) {
    payload = { type: 'button', body: { text: cut(x.text, 1024) },
      action: { buttons: x.buttons.slice(0, 3).map(b => ({ type: 'reply', reply: { id: cut(b.id, 256), title: cut(b.title, 20) } })) } };
  } else if (x.list && Array.isArray(x.list.sections)) {
    let left = 10;
    const sections = x.list.sections.map(s => {
      const rows = (s.rows || []).slice(0, Math.max(left, 0)).map(rw => {
        const row = { id: cut(rw.id, 200), title: cut(rw.title, 24) };
        if (rw.description) row.description = cut(rw.description, 72);
        return row;
      });
      left -= rows.length;
      return { title: cut(s.title, 24), rows };
    }).filter(s => s.rows.length);
    payload = { type: 'list', body: { text: cut(x.text, 1024) }, action: { button: cut(x.list.button, 20), sections } };
  }
  return { json: { to: String(x.to), text: cut(x.text, 4000),
    payload: payload && { messaging_product: 'whatsapp', recipient_type: 'individual', to: String(x.to), type: 'interactive', interactive: payload } } };
});
